<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{csrf_token()}}"><title>Masuk · StockFlow ERP</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><style>
*{box-sizing:border-box}body{margin:0;font-family:'DM Sans',sans-serif;color:#fff;background:#17143c}.login-page{min-height:100vh;display:grid;grid-template-columns:1.08fr .92fr}.hero{padding:47px clamp(30px,6vw,95px);display:flex;flex-direction:column;justify-content:space-between;position:relative;background:linear-gradient(135deg,#201653 0%,#5b35c8 52%,#8a4de0 100%);overflow:hidden}.hero:before,.hero:after{content:'';position:absolute;border-radius:50%;filter:blur(2px)}.hero:before{width:520px;height:520px;background:#aa7cff33;right:-170px;top:-190px}.hero:after{width:330px;height:330px;background:#25115344;left:-90px;bottom:-150px}.logo,.hero-content,.hero-footer{position:relative;z-index:1}.logo{display:flex;align-items:center;gap:11px;font:800 20px 'Plus Jakarta Sans'}.logo i{width:42px;height:42px;display:grid;place-items:center;background:#ffffff20;border:1px solid #ffffff25;border-radius:12px}.tag{display:inline-block;padding:8px 11px;border-radius:8px;background:#ffffff16;color:#e6dcff;font-weight:700;letter-spacing:1.5px;font-size:10px}.hero h1{font:800 clamp(38px,4.1vw,61px)/1.07 'Plus Jakarta Sans';letter-spacing:-2.6px;max-width:650px;margin:17px 0}.hero p{font-size:16px;line-height:1.65;color:#ddd2fa;max-width:520px}.stats{display:flex;gap:28px;margin-top:31px}.stat b{font:800 23px 'Plus Jakarta Sans';display:block}.stat small{color:#c5b6eb}.login-wrap{display:grid;place-items:center;padding:36px;background:#f8f7fc;color:#292742}.login-card{width:min(420px,100%);padding:38px;background:#fff;border:1px solid #eeebf5;border-radius:18px;box-shadow:0 18px 55px #32206712}.eyebrow{color:#6d4aff;font-weight:800;font-size:10px;letter-spacing:1.5px}.login-card h2{font:800 29px 'Plus Jakarta Sans';letter-spacing:-1.1px;margin:10px 0}.muted{color:#8b89a3;line-height:1.6}.field{margin-top:19px}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:8px}.input-wrap{position:relative}.input-wrap i{position:absolute;left:15px;top:15px;color:#aaa6bb}.input-wrap input{width:100%;height:48px;padding:0 16px 0 42px;border:1px solid #dedbe9;border-radius:10px;font:14px inherit;outline:0}.input-wrap input:focus{border-color:#8067ef;box-shadow:0 0 0 4px #6d4aff14}.login-btn{border:0;width:100%;height:50px;border-radius:10px;background:linear-gradient(135deg,#7657ee,#5732c1);color:#fff;font:700 14px inherit;margin-top:25px;cursor:pointer;box-shadow:0 11px 25px #6340d43b}.login-btn:hover{transform:translateY(-1px)}.error{font-size:12px;color:#dc2626;margin-top:6px}.login-link{color:#6845df;text-decoration:none;font-weight:700}.hero-footer{color:#baace1;font-size:12px}@media(max-width:850px){.login-page{grid-template-columns:1fr}.hero{display:none}.login-wrap{min-height:100vh;padding:20px}.login-card{padding:28px}}</style></head><body><div class="login-page"><section class="hero"><div class="logo"><i class="fa-solid fa-cubes-stacked"></i>STOCKFLOW</div><div class="hero-content"><div class="tag">SMART INVENTORY MANAGEMENT</div><h1>Kelola stok dengan lebih cerdas.</h1><p>Satu dashboard untuk memantau persediaan, pergerakan barang, dan seluruh aktivitas operasional secara real-time.</p><div class="stats"><div class="stat"><b>100%</b><small>Data terpusat</small></div><div class="stat"><b>24/7</b><small>Siap dipantau</small></div><div class="stat"><b>Fast</b><small>Proses efisien</small></div></div></div><div class="hero-footer">© {{date('Y')}} StockFlow ERP · Inventory made effortless</div></section><section class="login-wrap">{{ $slot }}</section></div></body></html>
<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('input[type="password"]').forEach(function(input){const wrap=input.parentElement;wrap.style.position='relative';input.style.paddingRight='42px';const button=document.createElement('button');button.type='button';button.style.cssText='position:absolute;right:10px;top:50%;transform:translateY(-50%);border:0;background:transparent;color:#8b89a3;cursor:pointer;padding:5px';button.innerHTML='<i class="fa-regular fa-eye"></i>';button.addEventListener('click',function(){const visible=input.type==='text';input.type=visible?'password':'text';button.innerHTML=visible?'<i class="fa-regular fa-eye"></i>':'<i class="fa-regular fa-eye-slash"></i>'});wrap.appendChild(button)});document.querySelectorAll('a[href*="password/request"]').forEach(function(link){link.remove()})})</script>
<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.login-link').forEach(function(link){link.remove()});document.querySelectorAll('input[type="password"] + button').forEach(function(button){button.style.right='4px'})})</script>
<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.input-wrap button').forEach(function(button){button.style.right='22px'})})</script>
<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.input-wrap button').forEach(function(button){button.style.setProperty('right','8px','important');button.style.setProperty('width','32px','important');button.style.setProperty('height','32px','important');button.style.setProperty('padding','0','important');button.style.setProperty('display','grid','important');button.style.setProperty('place-items','center','important');button.style.setProperty('transform','translateY(-50%)','important')})})</script>
